<script setup>
import { computed, nextTick, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import DemoClientChart from './DemoClientChart.vue';
import { demoClientRecordIds } from './recordIds';
import ClientQuickLook from '../../components/clients/ClientQuickLook.vue';
import { useClientQuickLook } from '../../composables/useClientQuickLook.js';
import { demoClients, demoProviders, demoStaff, demoStaffById, demoDateLabel, demoDay } from './people';
const props = defineProps({ section: {type: String, required: true} });
const route = useRoute(), router = useRouter();
const slug = computed(() => String(route.params.organizationSlug || 'meadowbrook'));
const search = ref(String(route.query.search || '')), scope = ref(route.query.scope === 'mine' ? 'mine' : 'practice'), providerFilter = ref(''), sort = ref('name');
const searchInput = ref(null);
const {quickViewClient,quickViewPinned,scheduleQuickView,cancelQuickView,pinClientPanel,closeClientPanel,cancelQuickViewClose,scheduleQuickViewClose}=useClientQuickLook();
const initials = name => name.split(' ').map(part => part[0]).join('');
const date = demoDateLabel;
const normalized = value => String(value || '').toLowerCase().replaceAll('.', '');
const filteredClients = computed(() => demoClients.filter(client => (scope.value !== 'mine' || client.provider_id === 990111) && (!providerFilter.value || scope.value === 'mine' || client.provider_id === Number(providerFilter.value)) && normalized([client.full_name, client.initials, client.provider_name, client.focus, client.service].join(' ')).includes(normalized(search.value))).sort((a, b) => sort.value === 'visit' ? a.next_date.localeCompare(b.next_date) : a.full_name.localeCompare(b.full_name)));
function chartLink(client) { return { path: `/${slug.value}/clients`, query: { clientId: String(client.id) } }; }
function setScope(value) { scope.value = value; providerFilter.value = ''; router.replace({query: {...route.query, scope: value}}); }
function applySearch() { searchInput.value?.blur(); }
function clearSearch() { search.value = ''; providerFilter.value = ''; }
const previewClient=computed(()=>quickViewClient.value?{...quickViewClient.value,client_type:quickViewClient.value.service,insurance_type_label:quickViewClient.value.payer,cleared_to_start:quickViewClient.value.status==='ACTIVE',guardian_portal_enabled:!quickViewClient.value.portal.toLowerCase().includes('pending')}:null);
function openChart(client){closeClientPanel();router.push(chartLink(client));}
const quickPresentation={
  getInitialsStyle:()=>({background:'#2467a7'}),getClientDisplay:client=>client.initials,
  getStatusPillStyle:()=>({background:'#edf5ff',color:'#205780'}),formatClientStatus:client=>client.status==='ACTIVE'?'Active':'Intake',
  affiliationDisplayLabel:()=> 'Meadowbrook Therapy',formatDate:value=>value?date(value):'—',
  getDocumentStatusTone:()=> 'complete',getDocumentStatusIcon:()=> '✓',formatDocumentStatusSummary:client=>client.note_status,
  roiExpiryClass:()=>''
};
const showAllStaff = ref(demoStaffById(route.query.providerId)?.is_provider === false), staffSearch = ref(''), selectedStaff = ref(demoStaffById(route.query.providerId) || demoProviders[0]), profileTab = ref('overview'), profileHeading = ref(null);
const filteredStaff = computed(() => (showAllStaff.value ? demoStaff : demoProviders).filter(person => normalized([person.name, person.credential, person.role_label, ...person.specialties].join(' ')).includes(normalized(staffSearch.value))));
const profileTabs = computed(() => selectedStaff.value?.is_provider ? [{id:'overview',label:'Overview'}, {id:'caseload',label:'Caseload'}, {id:'schedule',label:'Schedule'}, {id:'documentation',label:'Documentation'}, {id:'credentials',label:'Credentials'}, {id:'plotline',label:'Plotline'}] : [{id:'overview',label:'Overview'}, {id:'responsibilities',label:'Responsibilities'}, {id:'access',label:'Practice access'}, {id:'plotline',label:'Plotline'}]);
const clientsFor = person => demoClients.filter(client => client.provider_id === person.id);
async function chooseStaff(person) { selectedStaff.value = person; profileTab.value = 'overview'; await nextTick(); if (window.innerWidth < 1000) { profileHeading.value?.focus({preventScroll: true}); profileHeading.value?.scrollIntoView({block:'start', behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth'}); } }
function toggleStaff() { showAllStaff.value = !showAllStaff.value; if (!showAllStaff.value && !selectedStaff.value.is_provider) chooseStaff(demoProviders[0]); }
function profileTabKey(event) { if (!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)) return; event.preventDefault(); const items = profileTabs.value, index = items.findIndex(item => item.id === profileTab.value); const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : (index + (event.key === 'ArrowRight' ? 1 : -1) + items.length) % items.length; profileTab.value = items[next].id; document.getElementById(`profile-tab-${profileTab.value}`)?.focus(); }
watch(() => route.query.search, value => { search.value = String(value || ''); });
watch(() => route.query.scope, value => { scope.value = value === 'mine' ? 'mine' : 'practice'; });
watch(() => route.query.providerId, value => { const person = demoStaffById(value); if (person) { selectedStaff.value = person; profileTab.value = 'overview'; if (!person.is_provider) showAllStaff.value = true; } });
watch(() => route.query.clientId, closeClientPanel);
watch(() => props.section, closeClientPanel);
</script>

